package lk.lumina;
import java.sql.*;import java.time.*;import java.util.*;import java.math.*;
public final class Library{
 public static Timestamp now(){return Timestamp.from(Instant.now());}
 public static int setting(Connection c,String key)throws Exception{return Integer.parseInt(DB.one(c,"SELECT setting_value FROM settings WHERE setting_key=?",key).get("setting_value").toString());}
 public static void require(boolean condition,String message){if(!condition)throw new IllegalArgumentException(message);}
 public static void audit(Connection c,long uid,String action,String details)throws Exception{DB.update(c,"INSERT INTO audit_log(user_id,action,details,created_at) VALUES(?,?,?,?)",uid,action,details,now());}
 public static void notify(Connection c,long uid,String title,String message,String link,String key)throws Exception{if(DB.one(c,"SELECT id FROM notifications WHERE dedupe_key=?",key)==null)DB.update(c,"INSERT INTO notifications(user_id,title,message,link,dedupe_key,created_at) VALUES(?,?,?,?,?,?)",uid,title,message,link,key,now());}
 public static void reserve(long uid,long book,long branch)throws Exception{DB.tx(c->{require(DB.one(c,"SELECT id FROM copies WHERE book_id=? AND branch_id=? AND status='AVAILABLE'",book,branch)==null,"This book is available at this branch. Borrow it at the circulation desk; a reservation is not required.");require(DB.one(c,"SELECT id FROM users WHERE id=? AND active=1",uid)!=null,"Member is inactive or missing.");var b=DB.one(c,"SELECT * FROM books WHERE id=? AND active=1 AND format<>'DIGITAL'",book);require(b!=null,"Choose an available physical title.");require(DB.one(c,"SELECT id FROM branches WHERE id=? AND active=1",branch)!=null,"Choose an active branch.");require(DB.one(c,"SELECT id FROM reservations WHERE user_id=? AND book_id=? AND status IN ('WAITING','READY')",uid,book)==null,"You already have an open reservation for this book.");long id=DB.update(c,"INSERT INTO reservations(user_id,book_id,branch_id,created_at) VALUES(?,?,?,?)",uid,book,branch,now());notify(c,uid,"Reservation confirmed","You have joined the collection queue. We will notify you when your copy is ready.","/reservations","reservation-"+id);for(var staff:DB.list(c,"SELECT id FROM users WHERE active=1 AND (role IN ('ADMIN','LIBRARIAN') OR (role='BRANCH_MANAGER' AND branch_id=?))",branch))notify(c,DB.id(staff,"id"),"New reservation","A reader has joined the reservation queue.","/reservations","staff-res-"+id+"-"+staff.get("id"));fulfill(c);return null;});}
 public static void cancelReservation(long uid,long id,boolean staff,Long branch)throws Exception{DB.tx(c->{var r=DB.one(c,"SELECT * FROM reservations WHERE id=?",id);require(r!=null&&(staff||DB.id(r,"user_id")==uid),"Reservation unavailable.");if(branch!=null)require(DB.id(r,"branch_id")==branch,"This reservation belongs to another branch.");require(List.of("WAITING","READY").contains(r.get("status")),"This reservation is already closed.");if(r.get("copy_id")!=null)DB.update(c,"UPDATE copies SET status='AVAILABLE' WHERE id=?",r.get("copy_id"));DB.update(c,"UPDATE reservations SET status='CANCELLED' WHERE id=?",id);notify(c,DB.id(r,"user_id"),"Reservation cancelled","Your reservation has been cancelled.","/reservations","cancel-res-"+id);fulfill(c);return null;});}
 public static void fulfill(Connection c)throws Exception{for(var r:DB.list(c,"SELECT r.* FROM reservations r JOIN users u ON u.id=r.user_id JOIN books b ON b.id=r.book_id WHERE r.status='WAITING' AND u.active=1 AND b.active=1 AND EXISTS(SELECT 1 FROM branches br WHERE br.id=r.branch_id AND br.active=1) ORDER BY r.created_at,r.id")){var copy=DB.one(c,"SELECT TOP 1 * FROM copies WHERE book_id=? AND branch_id=? AND status='AVAILABLE' ORDER BY id",r.get("book_id"),r.get("branch_id"));if(copy==null)continue;Timestamp until=Timestamp.from(Instant.now().plus(Duration.ofHours(setting(c,"reservation_hours"))));DB.update(c,"UPDATE copies SET status='RESERVED' WHERE id=?",copy.get("id"));DB.update(c,"UPDATE reservations SET status='READY',copy_id=?,ready_until=? WHERE id=?",copy.get("id"),until,r.get("id"));notify(c,DB.id(r,"user_id"),"Ready for collection","Your reserved book is ready. Collect it before "+Web.date(until)+" (Sri Lanka time).","/reservations","ready-"+r.get("id")+"-"+until.getTime());}}
 public static void borrow(long uid,long book,long branch)throws Exception{DB.tx(c->{var user=DB.one(c,"SELECT * FROM users WHERE id=? AND active=1",uid);require(user!=null,"Borrower not found or inactive.");require(DB.one(c,"SELECT id FROM branches WHERE id=? AND active=1",branch)!=null,"Choose an active branch.");var copy=DB.one(c,"SELECT TOP 1 c.* FROM copies c JOIN books b ON b.id=c.book_id WHERE c.book_id=? AND c.branch_id=? AND c.status='AVAILABLE' AND b.active=1 ORDER BY c.id",book,branch);require(copy!=null,"No available copy of this book remains at the selected branch.");long count=DB.id(DB.one(c,"SELECT COUNT(*) AS n FROM loans WHERE user_id=? AND kind='PHYSICAL' AND status IN ('ACTIVE','OVERDUE')",uid),"n");require(count<setting(c,"max_loans"),"Borrowing limit reached.");require(DB.one(c,"SELECT id FROM loans WHERE user_id=? AND kind='PHYSICAL' AND status IN ('ACTIVE','OVERDUE') AND due_at<?",uid,now())==null,"Return overdue books before borrowing again.");require(DB.one(c,"SELECT id FROM fines WHERE user_id=? AND status IN ('OUTSTANDING','PARTIALLY_PAID')",uid)==null,"Settle outstanding fines before borrowing.");Timestamp due=Timestamp.from(Instant.now().plus(Duration.ofDays(setting(c,"physical_days"))));long id=DB.update(c,"INSERT INTO loans(user_id,book_id,copy_id,kind,status,start_at,due_at) VALUES(?,?,?,'PHYSICAL','ACTIVE',?,?)",uid,book,copy.get("id"),now(),due);DB.update(c,"UPDATE copies SET status='BORROWED' WHERE id=?",copy.get("id"));notify(c,uid,"Book borrowed","Your physical book is due on "+Web.date(due)+" (Sri Lanka time).","/my-books","borrow-"+id);audit(c,uid,"Borrow book","Loan "+id);return null;});}
 public static void issue(long actor,long uid,long copyId,Long branch)throws Exception{DB.tx(c->{var user=DB.one(c,"SELECT * FROM users WHERE id=? AND active=1",uid);require(user!=null,"Borrower not found or inactive.");var copy=DB.one(c,"SELECT c.* FROM copies c JOIN books b ON b.id=c.book_id JOIN branches br ON br.id=c.branch_id WHERE c.id=? AND b.active=1 AND br.active=1",copyId);require(copy!=null,"Copy not found or book inactive.");if(branch!=null)require(DB.id(copy,"branch_id")==branch,"Choose a copy in your assigned branch.");var reservation=DB.one(c,"SELECT * FROM reservations WHERE copy_id=? AND user_id=? AND status='READY' AND ready_until>?",copyId,uid,now());require(copy.get("status").equals("AVAILABLE")||(copy.get("status").equals("RESERVED")&&reservation!=null),"Copy unavailable or reserved for another reader.");long count=DB.id(DB.one(c,"SELECT COUNT(*) AS n FROM loans WHERE user_id=? AND kind='PHYSICAL' AND status IN ('ACTIVE','OVERDUE')",uid),"n");require(count<setting(c,"max_loans"),"Borrowing limit reached.");require(DB.one(c,"SELECT id FROM loans WHERE user_id=? AND kind='PHYSICAL' AND status IN ('ACTIVE','OVERDUE') AND due_at<?",uid,now())==null,"Return overdue books before borrowing again.");require(DB.one(c,"SELECT id FROM fines WHERE user_id=? AND status IN ('OUTSTANDING','PARTIALLY_PAID')",uid)==null,"Settle outstanding fines before borrowing.");Timestamp due=Timestamp.from(Instant.now().plus(Duration.ofDays(setting(c,"physical_days"))));long id=DB.update(c,"INSERT INTO loans(user_id,book_id,copy_id,kind,status,start_at,due_at) VALUES(?,?,?,'PHYSICAL','ACTIVE',?,?)",uid,copy.get("book_id"),copyId,now(),due);DB.update(c,"UPDATE copies SET status='BORROWED' WHERE id=?",copyId);if(reservation!=null)DB.update(c,"UPDATE reservations SET status='FULFILLED' WHERE id=?",reservation.get("id"));notify(c,uid,"Book issued","Your physical book is due on "+Web.date(due)+" (Sri Lanka time).","/my-books","issue-"+id);audit(c,actor,"Issue book","Loan "+id);return null;});}
 public static void returnBook(long actor,long loan,Long branch)throws Exception{DB.tx(c->{var r=DB.one(c,"SELECT l.*,c.branch_id FROM loans l JOIN copies c ON c.id=l.copy_id WHERE l.id=? AND l.kind='PHYSICAL' AND l.status IN ('ACTIVE','OVERDUE')",loan);require(r!=null,"This loan has already been returned or is unavailable.");if(branch!=null)require(DB.id(r,"branch_id")==branch,"This loan belongs to another branch.");Workflows.assess(c,r);DB.update(c,"UPDATE loans SET status='RETURNED',returned_at=? WHERE id=?",now(),loan);DB.update(c,"UPDATE copies SET status='AVAILABLE' WHERE id=?",r.get("copy_id"));notify(c,DB.id(r,"user_id"),"Book returned","Your return has been recorded. Thank you for reading with Lumina.","/my-books","return-"+loan);audit(c,actor,"Return book","Loan "+loan);fulfill(c);return null;});}
 public static void reminders()throws Exception{DB.tx(c->{Timestamp now=now();Timestamp tomorrow=Timestamp.from(Instant.now().plus(Duration.ofDays(1)));for(var r:DB.list(c,"SELECT * FROM loans WHERE status IN ('ACTIVE','OVERDUE') AND due_at<=?",tomorrow)){long id=DB.id(r,"id");boolean expired=((Timestamp)r.get("due_at")).before(now);String type=r.get("kind").equals("DIGITAL")?"digital":"physical";if(expired)DB.update(c,"UPDATE loans SET status=? WHERE id=?",type.equals("digital")?"EXPIRED":"OVERDUE",id);notify(c,DB.id(r,"user_id"),expired?(type.equals("digital")?"Digital borrowing expired":"Book overdue"):"Borrowing ends soon",expired?"Review your bookshelf for borrowing status and next steps.":"Your borrowing period ends within 24 hours. Check My Books for the due date.","/my-books",(expired?"expired-":"due-")+id+"-"+((Timestamp)r.get("due_at")).getTime());}
  for(var r:DB.list(c,"SELECT * FROM reservations WHERE status='READY' AND ready_until<?",now)){DB.update(c,"UPDATE reservations SET status='EXPIRED' WHERE id=?",r.get("id"));DB.update(c,"UPDATE copies SET status='AVAILABLE' WHERE id=?",r.get("copy_id"));notify(c,DB.id(r,"user_id"),"Collection period ended","Your reservation expired before collection. You can reserve again.","/reservations","res-expired-"+r.get("id"));}fulfill(c);DB.update(c,"DELETE FROM reset_tokens WHERE expires_at<?",Timestamp.from(Instant.now().minus(Duration.ofDays(1))));return null;});}
}
